<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {X,History,Save,LockKeyhole,RotateCcw,AlertCircle} from 'lucide-vue-next';
import {api} from './api';
const props=defineProps<{assignment:any}>();const emit=defineEmits(['close','changed']);
const dialog=ref<HTMLDialogElement>();const current=ref({...props.assignment}),title=ref(''),requirements=ref(''),due=ref(''),maxSub=ref(5),maxEval=ref(3),reason=ref(''),tab=ref('settings'),records=ref<any[]>([]),busy=ref(false),error=ref(''),conflict=ref(false),saved=ref(''),historyError=ref('');let returnFocus:HTMLElement|null=null;
function localTime(value:string){const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function reset(){title.value=current.value.title;requirements.value=current.value.requirements;due.value=localTime(current.value.due_at);maxSub.value=current.value.max_submissions??5;maxEval.value=current.value.max_evaluations??3;reason.value='';}
reset();const dirty=computed(()=>title.value!==current.value.title||requirements.value!==current.value.requirements||due.value!==localTime(current.value.due_at)||maxSub.value!==(current.value.max_submissions??5)||maxEval.value!==(current.value.max_evaluations??3));
const canSave=computed(()=>dirty.value&&!!title.value.trim()&&!!requirements.value.trim()&&!!due.value&&!!reason.value.trim()&&!busy.value&&!conflict.value);
const actionName:Record<string,string>={EDIT:'修改任务规则',CLOSE:'手动结束',REOPEN:'重新开放'};
function time(s:string){return new Date(s).toLocaleString('zh-CN',{hour12:false});}
async function history(){historyError.value='';try{records.value=await api(`/assignments/${current.value.id}/history`);}catch(e:any){historyError.value=e.message;}}
function close(){if(busy.value)return;if((dirty.value||reason.value)&&!confirm('放弃本次未保存的作业管理输入？'))return;dialog.value?.close();emit('close');}
async function reload(){if((dirty.value||reason.value)&&!confirm('重新载入将放弃当前未保存的作业管理输入，确认继续？'))return;busy.value=true;error.value='';try{const rows=await api(`/courses/${current.value.course_id}/assignments`);const found=rows.find((a:any)=>a.id===current.value.id);if(!found)throw Error('作业已不可访问');current.value={...found};reset();conflict.value=false;await history();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function save(){if(!canSave.value)return;const d=new Date(due.value);if(!Number.isFinite(d.getTime())){error.value='请填写有效截止时间';return;}if(!current.value.manually_closed&&Date.parse(current.value.due_at)<=Date.now()&&!confirm('该作业已自然截止。保存新的未来截止时间后，将恢复学生作答与提交。确认延期？'))return;busy.value=true;error.value='';saved.value='';try{current.value=await api(`/assignments/${current.value.id}`,'PUT',{title:title.value,requirements:requirements.value,dueAt:due.value===localTime(current.value.due_at)?current.value.due_at:d.toISOString(),maxSubmissions:Number(maxSub.value),maxEvaluations:Number(maxEval.value),reason:reason.value,revision:current.value.management_revision});reset();saved.value='作业规则已更新，课程学生将收到提醒。';emit('changed');await history();}catch(e:any){error.value=e.message;conflict.value=e.status===409;}finally{busy.value=false;}}
async function changeState(){if(dirty.value){error.value='请先保存或重置未保存的任务要求，再改变开放状态。';return;}if(!reason.value.trim()){error.value='请填写变更原因，再改变开放状态。';return;}const closed=current.value.manually_closed;if(!confirm(closed?'重新开放后，学生可在截止前继续提交。确认开放？':'结束后停止新建作答和提交；已有草稿、评审与历史保留。确认结束？'))return;busy.value=true;error.value='';saved.value='';try{current.value=await api(`/assignments/${current.value.id}/state`,'POST',{action:closed?'REOPEN':'CLOSE',reason:reason.value,revision:current.value.management_revision});reset();saved.value=closed?'作业已重新开放。':'作业已手动结束，已有草稿仍可整理。';emit('changed');await history();}catch(e:any){error.value=e.message;conflict.value=e.status===409;}finally{busy.value=false;}}
function unload(e:BeforeUnloadEvent){if(dirty.value||reason.value||busy.value){e.preventDefault();e.returnValue='';}}
onMounted(async()=>{returnFocus=document.activeElement as HTMLElement;dialog.value?.showModal();await nextTick();await history();window.addEventListener('beforeunload',unload);});
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',unload);returnFocus?.focus();});
</script>
<template><Teleport to="body"><dialog ref="dialog" class="assignment-manager" aria-labelledby="assignment-manager-heading" @cancel.prevent="close"><header><div><span class="eyebrow">教师作业管理 · r{{ current.management_revision }}</span><h2 id="assignment-manager-heading">管理作业</h2></div><button class="icon-btn" aria-label="关闭作业管理" :disabled="busy" @click="close"><X :size="20"/></button></header><div class="assignment-manager-tabs list-tabs"><button :class="{active:tab==='settings'}" @click="tab='settings'">任务与开放状态</button><button :class="{active:tab==='history'}" @click="tab='history';history()"><History :size="14"/>变更记录</button></div>
<div class="assignment-manager-body"><p v-if="error" class="notice-error" role="alert"><AlertCircle :size="16"/>{{ error }}</p><button v-if="conflict" class="btn secondary" :disabled="busy" @click="reload">重新载入最新规则</button><p v-if="saved" class="management-success" role="status">{{ saved }}</p>
<form v-if="tab==='settings'" @submit.prevent="save"><div class="management-state"><strong>{{ current.manually_closed?'已手动结束':(Date.parse(current.due_at)<=Date.now()?'已自然截止':'按截止时间开放') }}</strong><span>{{ time(current.due_at) }} 截止</span></div><p class="management-help">量规已随作业锁定，作业管理中不可改绑；调整课程默认量规不影响本作业。</p><fieldset :disabled="busy||conflict"><label>作业标题<input v-model="title" maxlength="160" required /></label><label>任务要求<textarea v-model="requirements" rows="5" maxlength="4000" required /></label><label>截止时间（本地时区）<input v-model="due" type="datetime-local" required /></label><div class="limit-row"><label>最多提交版本数<input v-model.number="maxSub" type="number" min="0" max="50" step="1" /><span class="field-hint">0 表示不限。达到上限后学生仍可改草稿，但不能提交新版本。</span></label><label>同一版本最多批阅次数<input v-model.number="maxEval" type="number" min="0" max="20" step="1" /><span class="field-hint">0 表示不限。首次评分与复评都计入。</span></label></div><label>变更原因<textarea v-model="reason" rows="2" maxlength="1000" placeholder="说明要求调整、延期或结束的原因；会保存在教师变更记录中" required /></label></fieldset><footer><button type="button" class="btn secondary" :disabled="busy||conflict" @click="changeState"><RotateCcw v-if="current.manually_closed" :size="15"/><LockKeyhole v-else :size="15"/>{{ current.manually_closed?'重新开放作业':'结束作业' }}</button><div><button type="button" class="text-btn" :disabled="busy" @click="reset">重置输入</button><button type="submit" class="btn primary" :disabled="!canSave"><Save :size="15"/>{{ busy?'正在保存…':'保存规则' }}</button></div></footer></form>
<section v-else class="assignment-change-list"><p class="management-help">保留最近 100 次规则变更；仅任课教师可见。</p><p v-if="historyError" role="alert">{{ historyError }}<button class="text-btn" @click="history">重试</button></p><p v-else-if="!records.length" class="empty-text">还没有规则变更。当前作业规则为初始版本。</p><article v-for="r in records" :key="r.id"><div><strong>{{ actionName[r.action_type] }}</strong><span>r{{ r.revision_no }} · {{ r.actor_name }}</span></div><time>{{ time(r.created_at) }}</time><p>{{ r.reason }}</p><details><summary>查看变更前后规则</summary><div class="rule-comparison"><section v-for="side in ['before','after']" :key="side"><b>{{ side==='before'?'变更前':'变更后' }}</b><p>{{ r[side].title }}</p><p class="rule-requirements">{{ r[side].requirements }}</p><p>{{ time(r[side].due_at) }} 截止</p><p>{{ r[side].manually_closed?'手动结束':'按截止时间开放' }}</p></section></div></details></article></section></div></dialog></Teleport></template>
